exercises.starter_code:
public class Main {
    static void modify(int[] p) {}
    public static void main(String[] args) { int num = 5; }
}

exercises.solution:
public class Main {
    static void modify(int[] p) { p[0] *= 2; }
    public static void main(String[] args) {
        int[] num = {5};
        modify(num);
        System.out.println(num[0]);
    }
}

